5	use App\Services\Stripe\CommissionPayoutService;
6	use App\Services\Stripe\CommissionVoidService;
7	use Illuminate\Bus\Queueable;
8	use Illuminate\Contracts\Queue\ShouldQueue;
9	use Illuminate\Foundation\Bus\Dispatchable;
10	use Illuminate\Queue\InteractsWithQueue;
11	use Illuminate\Queue\SerializesModels;
12	use Illuminate\Support\Facades\Log;
13	
14	// V2: Core. Batch-processes all eligible commission payouts via CommissionPayoutService. Runs on daily cron.
15	class ProcessCommissionPayoutsJob implements ShouldQueue
16	{
17	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
18	
19	    // This job is now a lightweight orchestrator: it creates payout batches and
20	    // dispatches one ExecuteCommissionPayoutJob per batch. Stripe API calls happen
21	    // inside those child jobs, not here — so the timeout can be short.
22	    //
23	    // Retry guards:
24	    //   1. processEligiblePayouts re-dispatches any pending/collecting/transferring
25	    //      batches, so transient failures in child jobs are picked up next run.
26	    //   2. createPayoutBatch filters accrual entries on whereNull('payout_id') so
27	    //      we can't double-create a batch for the same ledger rows.
28	    //   3. ExecuteCommissionPayoutJob uses idempotent resume logic in processPayoutBatch
29	    //      — each step checks the payout's current status before executing.
30	    public int $tries = 3;
31	
32	    public int $timeout = 60;
33	
34	    public function __construct()
35	    {
36	        $this->onQueue('stripe');
37	    }
38	
39	    /**
40	     * Backoff between retries in seconds. 1 minute for the first retry
41	     * (typical network blip), 3 minutes for the second (longer Stripe outage).
42	     */
43	    public function backoff(): array
44	    {
45	        return [60, 180];
46	    }
47	
48	    public function handle(CommissionPayoutService $payoutService, CommissionVoidService $voidService): void
49	    {
50	        Log::info('Starting commission payout processing', [
51	            'attempt' => $this->attempts(),
52	        ]);
53	
54	        $payoutStats = $payoutService->processEligiblePayouts();
55	        Log::info('Commission payout processing complete', $payoutStats);
56	
57	        // Void commissions past their window for unconnected affiliates
58	        $voidStats = $voidService->processVoidableCommissions();
59	
60	        // Send warning notifications to affiliates approaching deadlines
61	        $warningStats = $voidService->sendGracePeriodWarnings();
62	
63	        if ($voidStats['voided_count'] > 0 || $warningStats['warnings_sent'] > 0) {
64	            Log::info('Commission void/warning processing complete', [
65	                ...$voidStats,
66	                ...$warningStats,
67	            ]);
68	        }
69	    }
70	
71	    public function failed(\Throwable $e): void
72	    {
73	        Log::error('Commission payout job failed after all retries', [
74	            'message' => $e->getMessage(),
75	        ]);
76	    }
77	}
