77	                'status' => 'failed',
78	                'failure_code' => 'job_exhausted',
79	                'failure_reason' => 'Payout job exhausted all Horizon retries after transient errors. '
80	                    .'Check wallet_debit_cents and stripe_payment_intent_id for manual reconciliation. '
81	                    .$e->getMessage(),
82	            ])->save();
83	        }
84	    }
