25	    //      batches, so transient failures in child jobs are picked up next run.
26	    //   2. createPayoutBatch filters accrual entries on whereNull('payout_id') so
27	    //      we can't double-create a batch for the same ledger rows.
28	    //   3. ExecuteCommissionPayoutJob uses idempotent resume logic in processPayoutBatch
29	    //      — each step checks the payout's current status before executing.
30	    public int $tries = 3;
31	
32	    public int $timeout = 60;
33	
34	    public function __construct()
35	    {
36	        $this->onQueue('stripe');
37	    }
38	
39	    /**
40	     * Backoff between retries in seconds. 1 minute for the first retry
41	     * (typical network blip), 3 minutes for the second (longer Stripe outage).
42	     */
43	    public function backoff(): array
44	    {
45	        return [60, 180];
46	    }
47	
