49	    {
50	        Log::info('Starting commission payout processing', [
51	            'attempt' => $this->attempts(),
52	        ]);
53	
54	        $payoutStats = $payoutService->processEligiblePayouts();
55	        Log::info('Commission payout processing complete', $payoutStats);
56	
57	        // Void commissions past their window for unconnected affiliates
58	        $voidStats = $voidService->processVoidableCommissions();
59	
