4	
5	use App\Models\Core\Site\Block;
6	use App\Services\Streaming\LiveStatusPoller;
7	use Illuminate\Bus\Queueable;
8	use Illuminate\Contracts\Queue\ShouldQueue;
9	use Illuminate\Foundation\Bus\Dispatchable;
10	use Illuminate\Queue\InteractsWithQueue;
11	use Illuminate\Queue\SerializesModels;
12	use Illuminate\Support\Facades\Log;
13	use Illuminate\Support\Facades\Redis;
14	
15	// Polls Twitch and Kick every 2 minutes for live status of all blocks with live_check_enabled=true.
16	class CheckStreamingLiveStatusJob implements ShouldQueue
17	{
18	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
19	
20	    public int $tries = 1;
21	
22	    public int $timeout = 90;
23	
24	    public function handle(LiveStatusPoller $poller): void
25	    {
26	        try {
27	            $kickRateLimited = Redis::exists('streaming:kick:rate_limited');
28	        } catch (\Throwable $e) {
29	            Log::error('streaming.redis_unavailable', ['message' => $e->getMessage()]);
30	            report($e);
31	
32	            return;
33	        }
34	
35	        if ($kickRateLimited) {
36	            Log::warning('streaming: skipping Kick — rate limited from previous cycle');
37	        }
38	
39	        $streamingPlatforms = config('sidest.streaming_platforms', []);
40	
41	        /** @var array<string, list<string>> $handlesByPlatform */
42	        $handlesByPlatform = array_fill_keys($streamingPlatforms, []);
43	
44	        // block_group='links' (NOT block_type='link') is the links/sections discriminator
45	        // in site.blocks. All other queries in the codebase use block_group.
46	        Block::query()
47	            ->where('block_group', 'links')
48	            ->whereRaw("settings->>'live_check_enabled' = ?", ['true'])
49	            ->whereNull('deleted_at')
50	            ->where('is_active', true)
51	            ->chunkById(500, function ($blocks) use (&$handlesByPlatform, $streamingPlatforms): void {
52	                foreach ($blocks as $block) {
53	                    $settings = is_array($block->settings) ? $block->settings : [];
54	                    $platform = $settings['platform'] ?? null;
55	                    $handle = $settings['handle'] ?? null;
56	
57	                    if (
58	                        $platform
59	                        && $handle
60	                        && in_array($platform, $streamingPlatforms, true)
61	                    ) {
62	                        $handlesByPlatform[$platform][] = $handle;
63	                    }
64	                }
65	            });
66	
67	        foreach ($handlesByPlatform as $platform => $handles) {
68	            if (empty($handles)) {
69	                continue;
70	            }
71	
72	            if ($platform === 'kick' && $kickRateLimited) {
73	                continue;
74	            }
75	
76	            try {
77	                $poller->poll($platform, $handles);
78	            } catch (\Throwable $e) {
79	                Log::error('streaming.poll_error', [
80	                    'platform' => $platform,
81	                    'message' => $e->getMessage(),
82	                ]);
83	            }
84	        }
85	    }
86	
87	    public function failed(\Throwable $e): void
88	    {
89	        Log::error('streaming.job_failed', ['message' => $e->getMessage()]);
90	    }
91	}
