12	
13	// Nightly cron: cancels commission payouts whose 60-day grace window
14	// has expired without the affiliate connecting Stripe Connect.
15	//
16	// Backstop for the UI promise on the affiliate dashboard ("payout will be
17	// voided in N days if you don't connect Stripe"). Without this job the
18	// per-payout void_at column was being written but never enforced — the
19	// older 30-day ledger-entry void path is unrelated and operates one layer
20	// below. Closes #CR-003.
21	class VoidExpiredPayoutsJob implements ShouldQueue
22	{
23	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
24	
25	    public int $tries = 3;
26	
27	    // Generous timeout: the partial index keeps the scan tight, but the
28	    // chunk loop voids ledger entries inside a transaction per payout.
29	    public int $timeout = 300;
30	
31	    public function __construct()
32	    {
33	        $this->onQueue('stripe');
34	    }
35	
36	    /** Backoff between retries: short for the first, longer for the second. */
37	    public function backoff(): array
38	    {
39	        return [60, 180];
40	    }
41	
42	    public function handle(CommissionVoidService $voidService): void
43	    {
44	        $stats = $voidService->processExpiredPayouts();
45	
46	        // Always emit a heartbeat — silence here would mask a stuck scheduler.
47	        // Promote to notice when real cancellations land so they stand out
48	        // from routine zero-action passes (matches markPendingFunding's pattern).
49	        if ($stats['cancelled_count'] > 0 || $stats['voided_entries'] > 0) {
50	            Log::notice('Expired payout void processing complete', $stats);
51	        } else {
52	            Log::info('Expired payout void processing complete', $stats);
53	        }
54	    }
55	
56	    public function failed(\Throwable $e): void
57	    {
58	        // Forward to the global handler so Nightwatch logs the failure.
59	        // Log::error gives us a structured breadcrumb in cloud logs even
60	        // if Nightwatch is offline.
61	        report($e);
62	
63	        Log::error('VoidExpiredPayoutsJob failed after all retries', [
64	            'message' => $e->getMessage(),
65	        ]);
66	    }
67	}
